import pyomo.environ as pyo

DATA = {
    "products": ["train", "plane"],
    "resources": ["wood", "paint"],
    "profit": {"train": 8, "plane": 10},
    "usage": {
        "wood": {"train": 3, "plane": 4},
        "paint": {"train": 3, "plane": 2},
    },
    "availability": {"wood": 120, "paint": 90},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    model.x = pyo.Var(model.P, within=pyo.NonNegativeIntegers)

    def obj_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def resource_rule(m, r):
        return sum(d["usage"][r][p] * m.x[p] for p in m.P) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "products": ["train", "plane"],
    "resources": ["wood", "paint"],
    "profit": {"train": 8, "plane": 10},
    "usage": {
        "wood": {"train": 3, "plane": 4},
        "paint": {"train": 3, "plane": 2},
    },
    "availability": {"wood": 120, "paint": 90},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    model.produce = pyo.Var(
        model.P,
        within=pyo.NonNegativeIntegers,
    )

    def profit_rule(m):
        return sum(d["profit"][p] * m.produce[p] for p in m.P)

    model.obj = pyo.Objective(expr=profit_rule, sense=pyo.maximize)

    def resource_rule(m, r):
        return sum(d["usage"][r][p] * m.produce[p] for p in m.P) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    return model
